  "check_code": "#!/usr/bin/env python3
import re
from pathlib import Path

from docx import Document


REPORT_NAME = "第一创业证券2023年新入职高风险岗位合规培训与闭卷测验总结报告.docx"


def _norm(value):
    return re.sub(r"[\s\u3000]+", "", str(value or "")).lower()


def _numbers(value):
    return [int(token.replace(",", "")) for token in re.findall(r"\d[\d,]*", str(value or ""))]


def _load_report(workspace):
    path = Path(workspace) / REPORT_NAME
    if not path.exists():
        raise FileNotFoundError(f"未找到报告：{REPORT_NAME}")
    return Document(path)


def _background_rows(document):
    expected_headers = ["类别", "分项", "数量", "口径/说明"]
    for table in document.tables:
        if not table.rows:
            continue
        headers = [_norm(cell.text) for cell in table.rows[0].cells]
        if all(_norm(header) in headers for header in expected_headers):
            return [[cell.text for cell in row.cells] for row in table.rows[1:]]
    raise ValueError("未找到年度背景统计表")


def _find_row(rows, category, item):
    for row in rows:
        if len(row) >= 3 and _norm(row[0]) == _norm(category) and _norm(row[1]) == _norm(item):
            return row
    raise ValueError(f"未找到目标行：{category}/{item}")


def check_annual_activity_table_corrected(workspace):
    try:
        rows = _background_rows(_load_report(workspace))
        row = _find_row(rows, "年度活动", "宣导及培训活动")
        values = _numbers(row[2])
        passed = values == [1190]
        return {
            "score": 1 if passed else 0,
            "detail": f"年度活动数量当前为{row[2]!r}；期望语义值为1,190次。",
        }
    except Exception as exc:
        return {"score": 0, "detail": f"校验失败：{exc}"}


def check_adjacent_background_values_preserved(workspace):
    try:
        rows = _background_rows(_load_report(workspace))
        total_hours = _find_row(rows, "年度时长", "合计")[2]
        organization = _find_row(rows, "组织背景", "员工/分支机构")[2]
        passed = _numbers(total_hours) == [3187] and _numbers(organization) == [3224, 59]
        return {
            "score": 1 if passed else 0,
            "detail": f"年度时长合计={total_hours!r}；员工/分支机构={organization!r}。",
        }
    except Exception as exc:
        return {"score": 0, "detail": f"校验失败：{exc}"}


def check_activity_row_noncount_fields_preserved(workspace):
    try:
        rows = _background_rows(_load_report(workspace))
        row = _find_row(rows, "年度活动", "宣导及培训活动")
        expected = ["年度活动", "宣导及培训活动", "正文表述为1,190余次"]
        actual = [row[0], row[1], row[3]]
        passed = actual == expected
        return {
            "score": 1 if passed else 0,
            "detail": f"目标行非数量字段={actual!r}；期望={expected!r}。",
        }
    except Exception as exc:
        return {"score": 0, "detail": f"校验失败：{exc}"}


def check_body_text_preserved(workspace):
    try:
        document = _load_report(workspace)
        paragraphs = {paragraph.text.strip() for paragraph in document.paragraphs if paragraph.text.strip()}
        required = {
            "第一创业证券股份有限公司2023年合规培训总时长为3,187小时，员工覆盖率100%，全年开展1,190余次合规宣导及培训活动。本专项项目是年度培训体系中针对新入职高风险岗位的强化环节，不能与年度全员培训人数重复相加。",
            "年度培训时长分项为法律法规与监管规则812小时、反洗钱与客户身份识别748小时、廉洁从业与员工行为管理596小时、业务线专项合规671小时、案例研讨及测试辅导360小时，合计3,187小时。活动批次明细合计1,196次，正文按披露口径概括为“全年开展1,190余次合规宣导及培训活动”。",
            "年度3,187小时培训时长及1,196次活动为公司全年合规培训背景，本项目36人数据是其中的专项管理单元。两组数据分别用于年度披露和项目闭环，不相互替代或直接推算人均效果。",
            "活动批次：分项合计1,196次，披露概括为1,190余次。",
        }
        missing = sorted(required - paragraphs)
        return {
            "score": 0 if missing else 1,
            "detail": "正文锚点均保持不变。" if not missing else f"正文锚点被改写或删除：{missing}",
        }
    except Exception as exc:
        return {"score": 0, "detail": f"校验失败：{exc}"}
